import collections
import hashlib
import json
import pathlib
import re

base = pathlib.Path(__file__).parent
data = json.loads((base / 'ir-price/samples.json').read_text())


def names_for(worker):
    names = {kind: {} for kind in ('fn', 'fl', 'ob')}
    for path in sorted((base / 'ir-price').glob(f'{worker}.callgrind.*')):
        for line in path.read_text().splitlines():
            match = re.match(r'^(c?fn|c?fl|c?fi|fe|c?ob)=\((\d+)\) (.*)', line)
            if match:
                kind, number, name = match.groups()
                kind = 'fl' if kind in ('fi', 'fe', 'cfi') else kind.removeprefix('c')
                assert number not in names[kind] or names[kind][number] == name
                names[kind][number] = name
    return names


def parse(path, names):
    self_cost = collections.Counter()
    arc_cost = collections.Counter()
    calls = collections.Counter()
    context = {'ob': '', 'fn': '', 'fl': '', 'cfn': ''}
    arc, count, total = False, 0, None
    for line in path.read_text().splitlines():
        match = re.match(r'^(c?fn|c?fl|c?fi|fe|c?ob)=(.*)', line)
        if match:
            kind, value = match.groups()
            number = re.match(r'^\((\d+)\)', value)
            space = 'fl' if kind in ('fi', 'fe', 'cfi') else kind.removeprefix('c')
            context[kind] = names[space][number[1]] if number else value
        if line.startswith('calls='):
            arc, count = True, int(line[6:].split()[0])
        cost = re.match(r'^(?:[+-]?\d+|\*) (\d+)\s*$', line)
        if cost:
            if arc:
                arc_cost[(context['fn'], context['cfn'])] += int(cost[1])
                calls[(context['fn'], context['cfn'])] += count
            else:
                self_cost[context['fn']] += int(cost[1])
            arc = False
        if line.startswith('totals:'):
            total = int(line.split()[1])
    assert sum(self_cost.values()) == total
    return self_cost, arc_cost, calls


parsed = {}
rows = []
for round_number, sample in enumerate(data['samples']):
    row = {'round': round_number}
    for arm in ('off_a', 'off_b'):
        worker = f'{round_number}-{arm}'
        names = names_for(worker)
        operations = sample[arm]['operations']['GET:/s/enr7ye']
        row[arm] = dict(operations)
        for mode in ('total', 'no_gc'):
            contrasts = []
            for i, window in enumerate(data['workers'][worker]['windows']):
                if window['unit'] != 'GET:/s/enr7ye' or window['mode'] != mode:
                    continue
                path = base / f'ir-price/{worker}.callgrind.{i + 1}'
                p = parse(path, names)
                parsed[(worker, mode, window['requests'])] = p
                contrasts.append((window['requests'], window, p))
            contrasts.sort(key=lambda item: item[0])
            empty, full = contrasts
            row[arm][mode] = {
                'dump': f'{worker}.callgrind.{data["workers"][worker]["windows"].index(full[1]) + 1}',
                'gc_segments': full[1]['gc_segments'],
                'gc_delta': {key: full[1]['after'][key] - full[1]['before'][key]
                             for key in ('count', 'minor_gc_count', 'major_gc_count', 'total_allocated_objects')},
            }
    row['aa_pct'] = {mode: 100 * (row['off_b'][f'instructions_{mode}'] /
                                     row['off_a'][f'instructions_{mode}'] - 1)
                     for mode in ('total', 'no_gc')}
    rows.append(row)
    print(json.dumps(row))
    for mode in ('total', 'no_gc'):
        delta = collections.Counter()
        for arm, sign in (('off_a', -1), ('off_b', 1)):
            for n, factor in ((0, -sign), (50, sign)):
                costs = parsed[(f'{round_number}-{arm}', mode, n)][0]
                for fn, value in costs.items():
                    delta[fn] += factor * value
        expected = 50 * (row['off_b'][f'instructions_{mode}'] - row['off_a'][f'instructions_{mode}'])
        assert abs(sum(delta.values()) - expected) < 0.001
        print(mode, 'delta per request', sum(delta.values()) / 50,
              sorted(delta.items(), key=lambda item: abs(item[1]), reverse=True)[:20])

(base / 'diagnosis-rounds.json').write_text(json.dumps(rows, indent=2) + '\n')

for worker, mode in [('0-off_b', 'total'), ('2-off_b', 'total'),
                     ('1-off_a', 'no_gc'), ('3-off_b', 'no_gc')]:
    costs, arcs, calls = parsed[(worker, mode, 50)]
    print('SPIKE', worker, mode)
    print('TOP SELF', costs.most_common(18))
    print('TOP ARCS', [(key, value, calls[key]) for key, value in arcs.most_common(25)])

signatures = []
for row in rows:
    for arm in ('off_a', 'off_b'):
        worker = f'{row["round"]}-{arm}'
        for mode in ('total', 'no_gc'):
            costs, arcs, calls = parsed[(worker, mode, 50)]
            matches = {fn: value for fn, value in costs.items()
                       if re.search(r'marshal_dump|deflate|yaml_emitter|unlink|rename|binwrite|file_s_|gc_(mark|sweep)', fn)}
            edges = [(caller, callee, calls[(caller, callee)], value)
                     for (caller, callee), value in arcs.items()
                     if re.search(r'marshal_dump|deflate|yaml_emitter|unlink|rename|binwrite|file_s_', callee)]
            print('SIGNATURE', worker, mode, json.dumps(matches), json.dumps(edges))
            selected = ('marshal_dump', 'rb_deflate_s_deflate', 'io_binwrite.part.0',
                        'rb_file_s_rename', 'rb_file_s_unlink',
                        'yaml_emitter_emit_mapping_start', 'yaml_emitter_analyze_scalar')
            signature = {'worker': worker, 'mode': mode,
                         'dump': row[arm][mode]['dump'],
                         'entry_edges': {fn: [
                             {'caller': caller, 'calls': calls[(caller, callee)], 'inclusive_Ir': value}
                             for (caller, callee), value in arcs.items() if callee == fn]
                             for fn in selected},
                         'selected_self_Ir': {fn: costs[fn] for fn in (
                             'deflate_slow', 'yaml_emitter_analyze_scalar', 'marshal_dump')},
                         'gc_delta': row[arm][mode]['gc_delta'],
                         'gc_segments': row[arm][mode]['gc_segments']}
            signatures.append(signature)

assert len(signatures) == 24
assert all(s['gc_delta']['count'] == s['gc_segments'] == 0 for s in signatures)
spikes = {(s['worker'], s['mode']) for s in signatures if s['entry_edges']['marshal_dump']}
assert spikes == {('0-off_b', 'total'), ('2-off_b', 'total'),
                  ('1-off_a', 'no_gc'), ('3-off_b', 'no_gc')}
for s in signatures:
    for fn in ('marshal_dump', 'rb_deflate_s_deflate', 'io_binwrite.part.0', 'rb_file_s_rename'):
        assert sum(edge['calls'] for edge in s['entry_edges'][fn]) == int((s['worker'], s['mode']) in spikes)

report = {
    'scope': 'One bounded post-hoc read-only analysis of existing off/off story dumps; no new workloads or measurements',
    'round_numbering': 'zero-based, matching original worker and dump names',
    'pinned_source_context': {
        'fixture': 'ruby-bench 351a39b77e6c06f4f4fa03148639b10a6bb0c716',
        'story_fetch': 'app/controllers/stories_controller.rb:391: Rails.cache.fetch("story #{short_id}", expires_in: 60, &block)',
        'rails_fetch': 'activesupport-8.1.4/lib/active_support/cache.rb:1095-1125: handle_expired_entry deletes expired entries; save_block_result_to_cache generates and writes them',
        'rails_file_store': 'activesupport-8.1.4/lib/active_support/cache/file_store.rb:125-132: serialize_entry followed by File.atomic_write',
        'rails_atomic_write': 'activesupport-8.1.4/lib/active_support/core_ext/file/atomic.rb:22-53: temporary file followed by rename',
        'source_hashes': 'See pins.files_sha256; these sources were independently rechecked in the export verifier',
    },
    'rounds': rows,
    'signatures': signatures,
    'observation': 'Total A/A upper tail is driven by 0-off_b and 2-off_b. Each contains one Marshal.dump, deflate, binary write and atomic rename; the other total windows contain none. No-GC has the same signature in 1-off_a and 3-off_b. All 24 off-story full windows have zero collections and zero excluded GC segments.',
    'interpretation': 'Different cache-regeneration work in stock off controls, not a Lowrail copy-plan effect or simply FileStore read latency. The pinned story fetch has expires_in:60 and workers share both routes with live clocks. A live-TTL phase crossing under instrumentation is the supported explanation, not counter arithmetic or GC phase.',
    'limits': 'Dumps contain native operations, not Ruby cache-event keys or per-entry expiry/read timestamps. They do not identify the precise refresh request or prove the expiry comparison itself. Residual small A/A variation is not fully attributed. No round was removed or reweighted and no corrected price is computed.',
    'future_prerequisite': 'Any separately authorized future price must explicitly certify per-window cache hit/regeneration mix and TTL/phase behavior without changing application semantics. This report authorizes no new runs.',
    'analysis_script': {'source': pathlib.Path(__file__).read_text(),
                        'sha256': hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest()},
}
(base / 'diagnosis.json').write_text(json.dumps(report, indent=2) + '\n')
print('Read-only diagnosis PASS: 48 dump self-cost sums, 12 A/A contrasts; 4 regeneration signatures; zero GC in 24 full off-story windows')
